window.RULES = [
  {id:'checks',page:129,category:{ru:'Основы',en:'Basics'},title:{ru:'Проверки навыков',en:'Skill checks'},text:{ru:'Бросьте 1d10 и прибавьте связанную характеристику и уровень навыка. Результат должен превысить сложность (DV); при встречной проверке ничья остаётся за защищающейся стороной.',en:'Roll 1d10 and add the linked STAT and Skill level. The result must beat the Difficulty Value (DV); in an opposed check, the defender wins ties.'}},
  {id:'critical-rolls',page:130,category:{ru:'Основы',en:'Basics'},title:{ru:'Критические броски',en:'Critical rolls'},text:{ru:'При натуральной 10 бросьте ещё 1d10 и прибавьте результат; при натуральной 1 бросьте ещё 1d10 и вычтите его. Повторные критические броски не происходят.',en:'On a natural 10, roll another 1d10 and add it; on a natural 1, roll another 1d10 and subtract it. The extra die does not trigger another critical roll.'}},
  {id:'difficulty',page:130,category:{ru:'Основы',en:'Basics'},title:{ru:'Сложность действий',en:'Difficulty values'},text:{ru:'Ориентиры DV: простая задача — 9, обычная — 13, трудная — 15, профессиональная — 17, героическая — 21, невероятная — 24, легендарная — 29.',en:'DV guidelines: simple 9, everyday 13, difficult 15, professional 17, heroic 21, incredible 24, legendary 29.'}},
  {id:'stats',page:78,category:{ru:'Создание',en:'Creation'},title:{ru:'Характеристики: полный пакет',en:'STATs: Complete Package'},text:{ru:'Для стандартного персонажа распределите 62 очка между десятью характеристиками. При создании каждая должна быть от 2 до 8.',en:'For a standard starting character, distribute 62 points across ten STATs. Each must be between 2 and 8 during creation.'}},
  {id:'skills',page:90,category:{ru:'Создание',en:'Creation'},title:{ru:'Навыки: полный пакет',en:'Skills: Complete Package'},text:{ru:'Распределите 86 очков навыков; максимум при создании — 6. Навыки с пометкой ×2 стоят два очка за уровень. Тринадцать базовых навыков должны быть не ниже 2; язык культурного происхождения получает 4 бесплатных уровня.',en:'Spend 86 Skill points; the creation maximum is 6. Skills marked ×2 cost two points per level. Thirteen basic skills must be at least 2; the language of your cultural background receives 4 free levels.'}},
  {id:'role',page:29,category:{ru:'Создание',en:'Creation'},title:{ru:'Роль',en:'Role'},text:{ru:'Выберите роль персонажа. Её особая способность начинается на уровне 4.',en:'Choose your character’s Role. Its Role Ability begins at rank 4.'}},
  {id:'derived',page:79,category:{ru:'Создание',en:'Creation'},title:{ru:'Здоровье и спасбросок',en:'Hit points and death save'},text:{ru:'Максимум HP равен 10 + 5 × среднее BODY и WILL, округлённое вверх. Порог серьёзного ранения — половина максимума HP с округлением вверх; базовый спасбросок от смерти равен BODY.',en:'Maximum HP equals 10 + 5 × the average of BODY and WILL, rounded up. The Seriously Wounded threshold is half maximum HP, rounded up; your base Death Save equals BODY.'}},
  {id:'humanity',page:80,category:{ru:'Создание',en:'Creation'},title:{ru:'Человечность и эмпатия',en:'Humanity and empathy'},text:{ru:'Начальная человечность равна EMP × 10. Потеря человечности, например из-за киберимплантов, может снизить текущую EMP: при переходе через десяток её значение уменьшается.',en:'Starting Humanity equals EMP × 10. Humanity loss, including from cyberware, can reduce current EMP when Humanity crosses a tens boundary.'}},
  {id:'movement',page:169,category:{ru:'Бой',en:'Combat'},title:{ru:'Передвижение',en:'Movement'},text:{ru:'За ход персонаж может переместиться на MOVE × 2 метров или ярдов, либо на MOVE клеток. Действие можно выполнить в середине перемещения и затем продолжить движение.',en:'On a turn, a character may move MOVE × 2 meters or yards, or MOVE squares. An Action can be taken partway through this movement before continuing.'}},
  {id:'armor',page:186,category:{ru:'Бой',en:'Combat'},title:{ru:'Броня и урон',en:'Armor and damage'},text:{ru:'Вычтите SP брони поражённой части тела из урона, затем снимите остаток с HP. Если урон прошёл, SP брони в этом месте уменьшается на 1 до ремонта. Некоторые источники урона обходят броню.',en:'Subtract the armor SP at the hit location from damage, then subtract the remainder from HP. If damage gets through, that location’s armor loses 1 SP until repaired. Some damage bypasses armor.'}},
  {id:'critical-injury',page:187,category:{ru:'Бой',en:'Combat'},title:{ru:'Критическое ранение',en:'Critical injury'},text:{ru:'Если при броске урона ближней или дальней атаки хотя бы два кубика показали 6, цель получает критическое ранение и 5 дополнительного урона непосредственно к HP, даже если основной урон не пробил броню.',en:'If at least two damage dice from a melee or ranged attack show 6, the target suffers a Critical Injury and 5 bonus damage directly to HP, even if the attack damage did not penetrate armor.'}},
  {id:'wounds',page:186,category:{ru:'Бой',en:'Combat'},title:{ru:'Состояния ранения',en:'Wound states'},text:{ru:'Когда HP ниже половины максимума с округлением вверх, персонаж серьёзно ранен и получает −2 ко всем действиям. При HP ниже 1 он смертельно ранен: −4 к действиям, −6 к MOVE (минимум 1) и спасбросок от смерти в начале каждого хода.',en:'Below half maximum HP, rounded up, a character is Seriously Wounded and takes −2 to all Actions. Below 1 HP they are Mortally Wounded: −4 to Actions, −6 MOVE (minimum 1), and a Death Save at the start of each turn.'}},
  {id:'death',page:188,category:{ru:'Бой',en:'Combat'},title:{ru:'Спасбросок от смерти',en:'Death saves'},text:{ru:'В начале хода при смертельном ранении бросьте d10 и прибавьте текущий штраф: сумма должна быть меньше BODY. Натуральная 10 означает провал. После каждого спасброска штраф увеличивается на 1; один провал смертелен. Стабилизация до 1 HP возвращает штраф к базовому значению.',en:'At the start of a turn while Mortally Wounded, roll d10 and add the current penalty: the total must be below BODY. A natural 10 fails automatically. The penalty increases by 1 after each save; one failure is fatal. Stabilization to 1 HP resets it to the base penalty.'}},
  {id:'healing',page:222,category:{ru:'Лечение',en:'Healing'},title:{ru:'Стабилизация и отдых',en:'Stabilization and rest'},text:{ru:'Стабилизация занимает действие: TECH + First Aid или Paramedic + 1d10 и превысьте DV 10, 13 или 15 в зависимости от тяжести ранения. После стабилизации полный день отдыха восстанавливает HP в размере BODY; смертельно раненый приходит к 1 HP и теряет сознание на минуту.',en:'Stabilization takes an Action: roll TECH + First Aid or Paramedic + 1d10 and beat DV 10, 13, or 15 depending on the wound state. Once stabilized, a full day of rest restores BODY HP; a Mortally Wounded patient returns to 1 HP and becomes unconscious for one minute.'}}
];
